package com.capitalone.chargeback;
import static org.junit.jupiter.api.Assertions.*;import java.util.*;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.*;import org.springframework.boot.test.context.*;import org.springframework.test.context.*;
@SpringBootTest(properties={"app.workflow-enabled=false","camunda.client.enabled=false","spring.datasource.url=jdbc:h2:mem:test;MODE=PostgreSQL;DB_CLOSE_DELAY=-1","spring.jpa.hibernate.ddl-auto=create-drop"}) class DisputeServiceTest { @Autowired DisputeService service; @Test void createsMultiTransactionCase(){var c=service.create(new CreateDisputeRequest("customer-001",List.of(new DisputeLine("txn-amazon","FRAUD"),new DisputeLine("txn-flipkart","FRAUD"))));assertEquals(2,c.items.size());assertEquals("SUBMITTED",c.status);}@Test void rejectsMissingReason(){assertThrows(IllegalArgumentException.class,()->service.create(new CreateDisputeRequest("customer-001",List.of(new DisputeLine("txn-restaurant","")))));}}
